import{_ as t,o as h,c as i,a2 as g}from"./chunks/framework.CqpfiAoK.js";const e=JSON.parse('{"title":"Bảng Tổng hợp Phân chia Kỷ nguyên","description":"","frontmatter":{},"headers":[],"relativePath":"vi/70-纪元划分总表.md","filePath":"vi/70-纪元划分总表.md"}'),c={name:"vi/70-纪元划分总表.md"};function a(u,n,d,o,l,r){return h(),i("div",null,[...n[0]||(n[0]=[g('<h1 id="bang-tong-hop-phan-chia-ky-nguyen" tabindex="-1">Bảng Tổng hợp Phân chia Kỷ nguyên <a class="header-anchor" href="#bang-tong-hop-phan-chia-ky-nguyen" aria-label="Permalink to &quot;Bảng Tổng hợp Phân chia Kỷ nguyên&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Số tài liệu</td><td>70</td></tr><tr><td>Mô-đun</td><td>Kỷ nguyên Lịch sử và Sự kiện Quan trọng</td></tr><tr><td>Từ khóa cốt lõi</td><td>Phân chia kỷ nguyên, phân kỳ lịch sử, thăng chiều bốn giai đoạn, dòng thời gian, cột mốc</td></tr></tbody></table><h2 id="_1-nguyen-tac-co-ban-cua-phan-chia-ky-nguyen" tabindex="-1">1. Nguyên tắc Cơ bản của Phân chia Kỷ nguyên <a class="header-anchor" href="#_1-nguyen-tac-co-ban-cua-phan-chia-ky-nguyen" aria-label="Permalink to &quot;1. Nguyên tắc Cơ bản của Phân chia Kỷ nguyên&quot;">​</a></h2><p>Việc phân chia kỷ nguyên lịch sử của Hengyuanzhou lấy con đường thăng chiều bốn giai đoạn làm khuôn khổ nền tảng, và trạng thái phát triển của cơ chế neo làm cơ sở phân kỳ cốt lõi. Mỗi kỷ nguyên tương ứng với một sự chuyển đổi căn bản trong mối quan hệ giữa nền văn minh và vũ trụ; ranh giới giữa các kỷ nguyên không phải là những điểm thời gian tùy tiện, mà được đánh dấu bởi những sự kiện quan trọng có ý nghĩa vũ trụ.</p><p>Việc phân chia kỷ nguyên tuân theo ba nguyên tắc:</p><ul><li><strong>Nguyên tắc tương ứng thăng chiều</strong>: mỗi kỷ nguyên lớn tương ứng với một giai đoạn trong con đường thăng chiều bốn giai đoạn, và các thời kỳ phân chia chi tiết bên trong kỷ nguyên tương ứng với những tiến bộ quan trọng trong giai đoạn đó</li><li><strong>Nguyên tắc đánh dấu sự kiện</strong>: điểm bắt đầu và kết thúc của một kỷ nguyên được xác định bởi những sự kiện quan trọng mang tính biểu tượng, không phải bởi việc chia thời gian đều đặn đơn giản</li><li><strong>Nguyên tắc trạng thái văn minh</strong>: mỗi kỷ nguyên được đặt tên theo đặc điểm cốt lõi của nền văn minh trong thời kỳ đó, phản ánh những mâu thuẫn chính và hướng phát triển của thời kỳ đó</li></ul><h2 id="_2-bang-tong-hop-cac-ky-nguyen-lich-su-hengyuanzhou" tabindex="-1">2. Bảng Tổng hợp các Kỷ nguyên Lịch sử Hengyuanzhou <a class="header-anchor" href="#_2-bang-tong-hop-cac-ky-nguyen-lich-su-hengyuanzhou" aria-label="Permalink to &quot;2. Bảng Tổng hợp các Kỷ nguyên Lịch sử Hengyuanzhou&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Số kỷ nguyên</th><th>Tên kỷ nguyên</th><th>Giai đoạn thăng chiều tương ứng</th><th>Sự kiện đánh dấu bắt đầu-kết thúc</th><th>Đặc điểm cốt lõi</th></tr></thead><tbody><tr><td>Kỷ nguyên thứ nhất</td><td>Thời kỳ Tiền-neo</td><td>Trước thăng chiều</td><td>Sinh ra vũ trụ→Thức tỉnh thế hệ đầu tiên neo</td><td>Tu luyện săn mồi chiếm ưu thế, đứt gãy văn minh thường xuyên</td></tr><tr><td>Kỷ nguyên thứ hai</td><td>Kỷ nguyên Thức tỉnh Neo</td><td>Bắt đầu xây dựng nền tảng thực tại</td><td>Thức tỉnh thế hệ đầu tiên neo→Ký Hiến chương Cộng sinh</td><td>Cơ chế neo được thiết lập, mầm mống tư tưởng chống săn mồi</td></tr><tr><td>Kỷ nguyên thứ ba</td><td>Giai đoạn Thiết lập Hệ thống Cộng sinh</td><td>Nền tảng thực tại</td><td>Ký Hiến chương Cộng sinh→Mở cửa hoàn toàn ba trăm hệ thống</td><td>Hệ thống cộng sinh được áp dụng, tái cấu trúc xã hội hoàn tất</td></tr><tr><td>Kỷ nguyên thứ tư</td><td>Kỷ nguyên Mở cửa và Kích hoạt Hệ thống</td><td>Bắt đầu trao quyền công nghệ</td><td>Mở cửa ba trăm hệ thống→Hoàn thành chiến lược kích hoạt 20%</td><td>Phổ biến tu luyện, đột phá trong kỹ thuật công trình luật</td></tr><tr><td>Kỷ nguyên thứ năm</td><td>Kỷ nguyên Thăng chiều Lần đầu</td><td>Trao quyền công nghệ→Tiến hóa ý thức</td><td>Thành công thăng chiều lần đầu→Thành lập Cộng hòa Tất cả các Chủng tộc</td><td>Xác minh thăng chiều văn minh, đột phá giao diện miền ý thức</td></tr><tr><td>Kỷ nguyên thứ sáu</td><td>Kỷ nguyên Cộng hòa Tất cả các Chủng tộc</td><td>Tiến hóa ý thức</td><td>Thành lập Cộng hòa Tất cả các Chủng tộc→Bắt đầu khám phá giữa các mặt phẳng</td><td>Thống nhất hệ thống tất cả các chủng tộc, cộng sinh ý thức tập thể</td></tr><tr><td>Kỷ nguyên thứ bảy</td><td>Kỷ nguyên Khám phá giữa các Mặt phẳng</td><td>Tiến hóa ý thức→Cộng sinh liên sao</td><td>Bắt đầu khám phá giữa các mặt phẳng→Xây dựng ban đầu mạng lưới liên sao</td><td>Phát hiện lớn các mặt phẳng, mở rộng mạng lưới neo</td></tr><tr><td>Kỷ nguyên thứ tám</td><td>Kỷ nguyên Cộng sinh Liên sao</td><td>Cộng sinh liên sao</td><td>Xây dựng mạng lưới liên sao→Thăng chiều tổng thể vũ trụ</td><td>Cộng sinh vũ trụ tất cả các chủng tộc, thăng chiều vũ trụ đang diễn ra</td></tr></tbody></table><h2 id="_3-khoang-thoi-gian-va-chi-so-quan-trong-cua-moi-ky-nguyen" tabindex="-1">3. Khoảng thời gian và Chỉ số Quan trọng của mỗi Kỷ nguyên <a class="header-anchor" href="#_3-khoang-thoi-gian-va-chi-so-quan-trong-cua-moi-ky-nguyen" aria-label="Permalink to &quot;3. Khoảng thời gian và Chỉ số Quan trọng của mỗi Kỷ nguyên&quot;">​</a></h2><p>Vì Hengyuanzhou bao gồm nhiều mặt phẳng và tốc độ thời gian khác nhau giữa các mặt phẳng, khoảng thời gian của các kỷ nguyên được lấy thời gian chuẩn của mặt phẳng chính làm cơ sở:</p><table tabindex="0"><thead><tr><th>Kỷ nguyên</th><th>Khoảng thời gian ước tính</th><th>Tỷ lệ bao phủ neo</th><th>Tỷ lệ người tu luyện</th><th>Chỉ số mức độ cộng sinh</th></tr></thead><tbody><tr><td>Thời kỳ Tiền-neo</td><td>Không thể khảo (thứ tự hàng tỷ năm)</td><td>0%</td><td>&lt;0,01%</td><td>&lt;10</td></tr><tr><td>Kỷ nguyên Thức tỉnh Neo</td><td>Hàng ngàn năm</td><td>1%→10%</td><td>0,01%→1%</td><td>10→30</td></tr><tr><td>Giai đoạn Thiết lập Hệ thống Cộng sinh</td><td>Hàng trăm năm</td><td>10%→40%</td><td>1%→10%</td><td>30→50</td></tr><tr><td>Kỷ nguyên Mở cửa và Kích hoạt Hệ thống</td><td>Hàng trăm năm</td><td>40%→70%</td><td>10%→30%</td><td>50→70</td></tr><tr><td>Kỷ nguyên Thăng chiều Lần đầu</td><td>Vài chục năm</td><td>70%→85%</td><td>30%→50%</td><td>70→80</td></tr><tr><td>Kỷ nguyên Cộng hòa Tất cả các Chủng tộc</td><td>Hàng trăm năm</td><td>85%→95%</td><td>50%→70%</td><td>80→90</td></tr><tr><td>Kỷ nguyên Khám phá giữa các Mặt phẳng</td><td>Hàng ngàn năm</td><td>95%→99%</td><td>70%→90%</td><td>90→95</td></tr><tr><td>Kỷ nguyên Cộng sinh Liên sao</td><td>Đang tiếp diễn</td><td>→100%</td><td>→100%</td><td>→100</td></tr></tbody></table><p>Tỷ lệ bao phủ neo đề cập đến tỷ lệ các khu vực phụ của mặt phẳng nơi phần cứng neo đã được triển khai; tỷ lệ người tu luyện đề cập đến tỷ lệ các sinh vật được bao phủ bởi hệ thống tu luyện chính thức; chỉ số mức độ cộng sinh là một chỉ số toàn diện đo lường mức độ cộng sinh của nền văn minh, với điểm tối đa là 100.</p><h2 id="_4-logic-noi-tai-cua-su-tien-hoa-ky-nguyen" tabindex="-1">4. Logic Nội tại của Sự tiến hóa Kỷ nguyên <a class="header-anchor" href="#_4-logic-noi-tai-cua-su-tien-hoa-ky-nguyen" aria-label="Permalink to &quot;4. Logic Nội tại của Sự tiến hóa Kỷ nguyên&quot;">​</a></h2><p>Sự tiến hóa kỷ nguyên của Hengyuanzhou không phải là dòng chảy thời gian tuyến tính, mà là một quá trình tiến hóa xoắn ốc đi lên. Mỗi kỷ nguyên giải quyết những mâu thuẫn cốt lõi còn lại từ kỷ nguyên trước đó, đồng thời tạo ra điều kiện phát triển cho kỷ nguyên tiếp theo:</p><ul><li>Mâu thuẫn cơ bản của Thời kỳ Tiền-neo là mâu thuẫn giữa săn mồi và cộng sinh, sự cực đoan của nó đã dẫn đến tất yếu của việc thức tỉnh neo</li><li>Kỷ nguyên Thức tỉnh Neo đã giải quyết vấn đề &quot;neo có tồn tại hay không&quot;, nhưng đã đối mặt với thách thức thể chế &quot;neo phục vụ cho ai&quot;</li><li>Giai đoạn Thiết lập Hệ thống Cộng sinh đã hoàn thành xây dựng thể chế, nhưng sự độc quyền tài nguyên tu luyện vẫn đang hạn chế sự tiến hóa của quần chúng</li><li>Kỷ nguyên Mở cửa và Kích hoạt Hệ thống đã phá vỡ sự độc quyền tu luyện, nhưng sự nhảy vọt về năng lực cá nhân đã mang lại những thách thức đạo đức và an toàn mới</li><li>Kỷ nguyên Thăng chiều Lần đầu đã xác minh tính khả thi của thăng chiều, nhưng thăng chiều của một mặt phẳng đơn lẻ không đủ để thúc đẩy sự tiến hóa tổng thể của vũ trụ</li><li>Kỷ nguyên Cộng hòa Tất cả các Chủng tộc đã thống nhất hệ thống văn minh, nhưng vũ trụ vẫn còn rất nhiều mặt phẳng và chủng tộc chưa được tiếp xúc</li><li>Kỷ nguyên Khám phá giữa các Mặt phẳng đã mở rộng biên giới văn minh, nhưng các mặt phẳng phân tán cần một kết nối liên sao chặt chẽ hơn</li><li>Kỷ nguyên Cộng sinh Liên sao cuối cùng chỉ đến mục tiêu tối thượng của thăng chiều tổng thể vũ trụ</li></ul><h2 id="_5-đinh-vi-ky-nguyen-hien-tai" tabindex="-1">5. Định vị Kỷ nguyên Hiện tại <a class="header-anchor" href="#_5-đinh-vi-ky-nguyen-hien-tai" aria-label="Permalink to &quot;5. Định vị Kỷ nguyên Hiện tại&quot;">​</a></h2><p>Theo trạng thái phát triển hiện tại của Hengyuanzhou, nền văn minh đang ở điểm then chốt của quá trình chuyển đổi từ Kỷ nguyên thứ ba (Giai đoạn Thiết lập Hệ thống Cộng sinh) sang Kỷ nguyên thứ tư (Kỷ nguyên Mở cửa và Kích hoạt Hệ thống). Hệ thống cộng sinh đã được áp dụng tại các mặt phẳng chính, công việc mở cửa ba trăm hệ thống đang được đẩy mạnh toàn diện, và chiến lược kích hoạt 20% đã bước vào giai đoạn thực hiện. Một số công nghệ cốt lõi ở tầng công trình luật (động cơ suy luận trái nhân, thiết bị luật không gian, hệ thống gương sao chép) đã chuyển từ phòng thí nghiệm sang sản xuất hàng loạt.</p><p>Nhiệm vụ cốt lõi của giai đoạn chuyển đổi này là: đảm bảo việc mở cửa ba trăm hệ thống thực sự mang lại lợi ích cho tất cả các sinh vật, đồng thời thông qua chiến lược kích hoạt 20% để đào tạo nhóm đầu tiên những người mạnh nhất mặt phẳng, tích lũy đủ năng lượng và kinh nghiệm cho lần thăng chiều đầu tiên.</p><h2 id="ket-luan" tabindex="-1">Kết luận <a class="header-anchor" href="#ket-luan" aria-label="Permalink to &quot;Kết luận&quot;">​</a></h2><p>Bảng Tổng hợp Phân chia Kỷ nguyên là khuôn khổ vĩ mô để hiểu sự tiến hóa lịch sử của Hengyuanzhou. Nó cô đọng lịch sử lâu dài của vũ trụ thành tám kỷ nguyên với logic nội tại rõ ràng, mỗi kỷ nguyên là một bậc thang cần thiết cho thăng chiều tổng thể vũ trụ. Các tài liệu tiếp theo sẽ trình bày chi tiết về mỗi kỷ nguyên và những sự kiện quan trọng bên trong nó.</p><h2 id="tai-lieu-lien-quan" tabindex="-1">Tài liệu liên quan <a class="header-anchor" href="#tai-lieu-lien-quan" aria-label="Permalink to &quot;Tài liệu liên quan&quot;">​</a></h2><ul><li>71-Thời kỳ Tiền-neo</li><li>72-Kỷ nguyên Thức tỉnh Neo</li><li>76-Cột mốc Thăng chiều Lần đầu</li></ul>',22)])])}const m=t(c,[["render",a]]);export{e as __pageData,m as default};
